tests/test_examples.py::test_example[examples/ApplicationELB.py-{
 "AWSTemplateFormatVersion": "2010-09-09",
 "Description": "AWS CloudFormation Sample Template: ELB with 2 EC2 instances",
 "Mappings": {
  "RegionMap": {
   "ap-northeast-1": {
    "AMI": "ami-9c03a89d"
   },
   "ap-southeast-1": {
    "AMI": "ami-66f28c34"
   },
   "eu-west-1": {
    "AMI": "ami-37c2f643"
   },
   "sa-east-1": {
    "AMI": "ami-a039e6bd"
   },
   "us-east-1": {
    "AMI": "ami-6411e20d"
   },
   "us-west-1": {
    "AMI": "ami-c9c7978c"
   },
   "us-west-2": {
    "AMI": "ami-fcff72cc"
   }
  }
 },
 "Outputs": {
  "URL": {
   "Description": "URL of the sample website",
   "Value": {
    "Fn::Join": [
     "",
     [
      "http://",
      {
       "Fn::GetAtt": [
        "ApplicationElasticLB",
        "DNSName"
       ]
      }
     ]
    ]
   }
  }
 },
 "Parameters": {
  "ApiServerPort": {
   "Default": "8889",
   "Description": "TCP/IP port of the api server",
   "Type": "String"
  },
  "InstanceType": {
   "AllowedValues": [
    "t1.micro",
    "m1.small",
    "m1.medium",
    "m1.large",
    "m1.xlarge",
    "m2.xlarge",
    "m2.2xlarge",
    "m2.4xlarge",
    "c1.medium",
    "c1.xlarge",
    "cc1.4xlarge",
    "cc2.8xlarge",
    "cg1.4xlarge"
   ],
   "ConstraintDescription": "must be a valid EC2 instance type.",
   "Default": "m1.small",
   "Description": "WebServer EC2 instance type",
   "Type": "String"
  },
  "KeyName": {
   "Default": "mark",
   "Description": "Name of an existing EC2 KeyPair to enable SSH access to the instance",
   "Type": "String"
  },
  "VpcId": {
   "Default": "vpc-82c514e6",
   "Type": "String"
  },
  "WebServerPort": {
   "Default": "8888",
   "Description": "TCP/IP port of the web server",
   "Type": "String"
  },
  "subnetA": {
   "Default": "subnet-096fd06d",
   "Type": "String"
  },
  "subnetB": {
   "Default": "subnet-1313ef4b",
   "Type": "String"
  }
 },
 "Resources": {
  "ApiInstance": {
   "Properties": {
    "ImageId": {
     "Fn::FindInMap": [
      "RegionMap",
      {
       "Ref": "AWS::Region"
      },
      "AMI"
     ]
    },
    "InstanceType": {
     "Ref": "InstanceType"
    },
    "KeyName": {
     "Ref": "KeyName"
    },
    "SecurityGroups": [
     {
      "Ref": "InstanceSecurityGroup"
     }
    ],
    "UserData": {
     "Fn::Base64": {
      "Ref": "ApiServerPort"
     }
    }
   },
   "Type": "AWS::EC2::Instance"
  },
  "ApplicationElasticLB": {
   "Properties": {
    "Name": "ApplicationElasticLB",
    "Scheme": "internet-facing",
    "Subnets": [
     {
      "Ref": "subnetA"
     },
     {
      "Ref": "subnetB"
     }
    ]
   },
   "Type": "AWS::ElasticLoadBalancingV2::LoadBalancer"
  },
  "InstanceSecurityGroup": {
   "Properties": {
    "GroupDescription": "Enable SSH and HTTP access on the inbound port",
    "SecurityGroupIngress": [
     {
      "CidrIp": "0.0.0.0/0",
      "FromPort": "22",
      "IpProtocol": "tcp",
      "ToPort": "22"
     },
     {
      "CidrIp": "0.0.0.0/0",
      "FromPort": {
       "Ref": "WebServerPort"
      },
      "IpProtocol": "tcp",
      "ToPort": {
       "Ref": "WebServerPort"
      }
     },
     {
      "CidrIp": "0.0.0.0/0",
      "FromPort": {
       "Ref": "ApiServerPort"
      },
      "IpProtocol": "tcp",
      "ToPort": {
       "Ref": "ApiServerPort"
      }
     }
    ]
   },
   "Type": "AWS::EC2::SecurityGroup"
  },
  "Listener": {
   "Properties": {
    "DefaultActions": [
     {
      "TargetGroupArn": {
       "Ref": "TargetGroupWeb"
      },
      "Type": "forward"
     }
    ],
    "LoadBalancerArn": {
     "Ref": "ApplicationElasticLB"
    },
    "Port": "80",
    "Protocol": "HTTP"
   },
   "Type": "AWS::ElasticLoadBalancingV2::Listener"
  },
  "ListenerRuleApi": {
   "Properties": {
    "Actions": [
     {
      "TargetGroupArn": {
       "Ref": "TargetGroupApi"
      },
      "Type": "forward"
     }
    ],
    "Conditions": [
     {
      "Field": "path-pattern",
      "Values": [
       "/api/*"
      ]
     }
    ],
    "ListenerArn": {
     "Ref": "Listener"
    },
    "Priority": "1"
   },
   "Type": "AWS::ElasticLoadBalancingV2::ListenerRule"
  },
  "TargetGroupApi": {
   "Properties": {
    "HealthCheckIntervalSeconds": "30",
    "HealthCheckProtocol": "HTTP",
    "HealthCheckTimeoutSeconds": "10",
    "HealthyThresholdCount": "4",
    "Matcher": {
     "HttpCode": "200"
    },
    "Name": "ApiTarget",
    "Port": {
     "Ref": "ApiServerPort"
    },
    "Protocol": "HTTP",
    "Targets": [
     {
      "Id": {
       "Ref": "ApiInstance"
      },
      "Port": {
       "Ref": "ApiServerPort"
      }
     }
    ],
    "UnhealthyThresholdCount": "3",
    "VpcId": {
     "Ref": "VpcId"
    }
   },
   "Type": "AWS::ElasticLoadBalancingV2::TargetGroup"
  },
  "TargetGroupWeb": {
   "Properties": {
    "HealthCheckIntervalSeconds": "30",
    "HealthCheckProtocol": "HTTP",
    "HealthCheckTimeoutSeconds": "10",
    "HealthyThresholdCount": "4",
    "Matcher": {
     "HttpCode": "200"
    },
    "Name": "WebTarget",
    "Port": {
     "Ref": "WebServerPort"
    },
    "Protocol": "HTTP",
    "Targets": [
     {
      "Id": {
       "Ref": "WebInstance"
      },
      "Port": {
       "Ref": "WebServerPort"
      }
     }
    ],
    "UnhealthyThresholdCount": "3",
    "VpcId": {
     "Ref": "VpcId"
    }
   },
   "Type": "AWS::ElasticLoadBalancingV2::TargetGroup"
  },
  "WebInstance": {
   "Properties": {
    "ImageId": {
     "Fn::FindInMap": [
      "RegionMap",
      {
       "Ref": "AWS::Region"
      },
      "AMI"
     ]
    },
    "InstanceType": {
     "Ref": "InstanceType"
    },
    "KeyName": {
     "Ref": "KeyName"
    },
    "SecurityGroups": [
     {
      "Ref": "InstanceSecurityGroup"
     }
    ],
    "UserData": {
     "Fn::Base64": {
      "Ref": "WebServerPort"
     }
    }
   },
   "Type": "AWS::EC2::Instance"
  }
 }
}
]

tests/test_examples.py::test_example[examples/DynamoDB_Tables_OnDemand.py-{
 "Conditions": {
  "OnDemand": {
   "Fn::Equals": [
    {
     "Ref": "BillOnDemand"
    },
    "true"
   ]
  }
 },
 "Description": "Create two dynamodb tables with conditional on-demand billing. One with global secondary index and one without",
 "Outputs": {
  "GSITable": {
   "Description": "Table with a Global Secondary Index",
   "Value": {
    "Ref": "GSITable"
   }
  }
 },
 "Parameters": {
  "BillOnDemand": {
   "AllowedPattern": "(false|true)",
   "Default": "true",
   "Type": "String"
  },
  "HashKeyElementName": {
   "AllowedPattern": "[a-zA-Z0-9]*",
   "ConstraintDescription": "must contain only alphanumberic characters",
   "Description": "HashType PrimaryKey Name",
   "MaxLength": "2048",
   "MinLength": "1",
   "Type": "String"
  },
  "HashKeyElementType": {
   "AllowedPattern": "[S|N]",
   "ConstraintDescription": "must be either S or N",
   "Default": "S",
   "Description": "HashType PrimaryKey Type",
   "MaxLength": "1",
   "MinLength": "1",
   "Type": "String"
  },
  "ReadCapacityUnits": {
   "ConstraintDescription": "should be between 5 and 10000",
   "Default": "5",
   "Description": "Provisioned read throughput",
   "MaxValue": "10000",
   "MinValue": "5",
   "Type": "Number"
  },
  "SecondaryIndexHashDataType": {
   "AllowedPattern": "[S|N|B]",
   "ConstraintDescription": "S for string data, N for numeric data, or B for binary data",
   "Default": "S",
   "Description": "Secondary Index: Primary Key Data Type",
   "MaxLength": "1",
   "MinLength": "1",
   "Type": "String"
  },
  "SecondaryIndexHashName": {
   "AllowedPattern": "[a-zA-Z0-9]*",
   "ConstraintDescription": "must contain only alphanumberic characters",
   "Default": "tokenType",
   "Description": "Secondary Index: Primary Key Field",
   "MaxLength": "2048",
   "MinLength": "1",
   "Type": "String"
  },
  "SecondaryIndexRangeDataType": {
   "AllowedPattern": "[S|N|B]",
   "ConstraintDescription": "S for string data, N for numeric data, or B for binary data",
   "Default": "S",
   "Description": "Secondary Index: Range Key Data Type",
   "MaxLength": "1",
   "MinLength": "1",
   "Type": "String"
  },
  "TableIndexDataType": {
   "AllowedPattern": "[S|N|B]",
   "ConstraintDescription": "S for string data, N for numeric data, or B for binary data",
   "Default": "S",
   "Description": " Table: Primary Key Data Type",
   "MaxLength": "1",
   "MinLength": "1",
   "Type": "String"
  },
  "TableIndexName": {
   "AllowedPattern": "[a-zA-Z0-9]*",
   "ConstraintDescription": "must contain only alphanumberic characters",
   "Default": "id",
   "Description": "Table: Primary Key Field",
   "MaxLength": "2048",
   "MinLength": "1",
   "Type": "String"
  },
  "WriteCapacityUnits": {
   "ConstraintDescription": "should be between 5 and 10000",
   "Default": "10",
   "Description": "Provisioned write throughput",
   "MaxValue": "10000",
   "MinValue": "5",
   "Type": "Number"
  },
  "refreshSecondaryIndexRangeName": {
   "AllowedPattern": "[a-zA-Z0-9]*",
   "ConstraintDescription": "must contain only alphanumberic characters",
   "Default": "tokenUpdatedTime",
   "Description": "Secondary Index: Range Key Field",
   "MaxLength": "2048",
   "MinLength": "1",
   "Type": "String"
  }
 },
 "Resources": {
  "GSITable": {
   "Properties": {
    "AttributeDefinitions": [
     {
      "AttributeName": {
       "Ref": "TableIndexName"
      },
      "AttributeType": {
       "Ref": "TableIndexDataType"
      }
     },
     {
      "AttributeName": {
       "Ref": "SecondaryIndexHashName"
      },
      "AttributeType": {
       "Ref": "SecondaryIndexHashDataType"
      }
     },
     {
      "AttributeName": {
       "Ref": "refreshSecondaryIndexRangeName"
      },
      "AttributeType": {
       "Ref": "SecondaryIndexRangeDataType"
      }
     }
    ],
    "BillingMode": {
     "Fn::If": [
      "OnDemand",
      "PAY_PER_REQUEST",
      "PROVISIONED"
     ]
    },
    "GlobalSecondaryIndexes": [
     {
      "IndexName": "SecondaryIndex",
      "KeySchema": [
       {
        "AttributeName": {
         "Ref": "SecondaryIndexHashName"
        },
        "KeyType": "HASH"
       },
       {
        "AttributeName": {
         "Ref": "refreshSecondaryIndexRangeName"
        },
        "KeyType": "RANGE"
       }
      ],
      "Projection": {
       "ProjectionType": "ALL"
      },
      "ProvisionedThroughput": {
       "Fn::If": [
        "OnDemand",
        {
         "Ref": "AWS::NoValue"
        },
        {
         "ReadCapacityUnits": {
          "Ref": "ReadCapacityUnits"
         },
         "WriteCapacityUnits": {
          "Ref": "WriteCapacityUnits"
         }
        }
       ]
      }
     }
    ],
    "KeySchema": [
     {
      "AttributeName": {
       "Ref": "TableIndexName"
      },
      "KeyType": "HASH"
     }
    ],
    "ProvisionedThroughput": {
     "Fn::If": [
      "OnDemand",
      {
       "Ref": "AWS::NoValue"
      },
      {
       "ReadCapacityUnits": {
        "Ref": "ReadCapacityUnits"
       },
       "WriteCapacityUnits": {
        "Ref": "WriteCapacityUnits"
       }
      }
     ]
    }
   },
   "Type": "AWS::DynamoDB::Table"
  },
  "myDynamoDBTable": {
   "Properties": {
    "AttributeDefinitions": [
     {
      "AttributeName": {
       "Ref": "HashKeyElementName"
      },
      "AttributeType": {
       "Ref": "HashKeyElementType"
      }
     }
    ],
    "BillingMode": {
     "Fn::If": [
      "OnDemand",
      "PAY_PER_REQUEST",
      "PROVISIONED"
     ]
    },
    "KeySchema": [
     {
      "AttributeName": {
       "Ref": "HashKeyElementName"
      },
      "KeyType": "HASH"
     }
    ],
    "ProvisionedThroughput": {
     "Fn::If": [
      "OnDemand",
      {
       "Ref": "AWS::NoValue"
      },
      {
       "ReadCapacityUnits": {
        "Ref": "ReadCapacityUnits"
       },
       "WriteCapacityUnits": {
        "Ref": "WriteCapacityUnits"
       }
      }
     ]
    }
   },
   "Type": "AWS::DynamoDB::Table"
  }
 }
}
]

tests/test_examples.py::test_example[examples/Backup.py-{
 "AWSTemplateFormatVersion": "2010-09-09",
 "Description": "AWS Backup",
 "Resources": {
  "Backup": {
   "Properties": {
    "BackupPlan": {
     "BackupPlanName": "BackupPlan",
     "BackupPlanRule": [
      {
       "CopyActions": [
        {
         "DestinationBackupVaultArn": "arn:aws:backup:ca-central-1:111112222212:backup-vault:TestVault",
         "Lifecycle": {
          "DeleteAfterDays": 31
         }
        }
       ],
       "Lifecycle": {
        "DeleteAfterDays": 31
       },
       "RecoveryPointTags": {
        "Classifier": "Classifier",
        "Environment": "Environment",
        "Project": "Project"
       },
       "RuleName": "Rule 1",
       "ScheduleExpression": "cron(0 0/12 * * ? *)",
       "TargetBackupVault": {
        "Ref": "Vault"
       }
      }
     ]
    },
    "BackupPlanTags": {
     "Classifier": "Classifier",
     "Environment": "Environment",
     "Project": "Project"
    }
   },
   "Type": "AWS::Backup::BackupPlan"
  },
  "BackupServiceRole": {
   "Properties": {
    "AssumeRolePolicyDocument": {
     "Statement": [
      {
       "Action": [
        "sts:AssumeRole"
       ],
       "Effect": "Allow",
       "Principal": {
        "Service": [
         "backup.amazonaws.com"
        ]
       }
      }
     ]
    },
    "ManagedPolicyArns": [
     "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup",
     "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
    ]
   },
   "Type": "AWS::IAM::Role"
  },
  "StorageBackupSelectionByTags": {
   "Properties": {
    "BackupPlanId": {
     "Ref": "Backup"
    },
    "BackupSelection": {
     "IamRoleArn": {
      "Fn::GetAtt": [
       "BackupServiceRole",
       "Arn"
      ]
     },
     "ListOfTags": [
      {
       "ConditionKey": "Backup",
       "ConditionType": "STRINGEQUALS",
       "ConditionValue": "True"
      }
     ],
     "SelectionName": "MySelection"
    }
   },
   "Type": "AWS::Backup::BackupSelection"
  },
  "Vault": {
   "Properties": {
    "BackupVaultName": "my-backup-vault",
    "BackupVaultTags": {
     "Classifier": "Classifier",
     "Environment": "Environment",
     "Project": "Project"
    }
   },
   "Type": "AWS::Backup::BackupVault"
  }
 }
}
]

