     "Ref": "ScaleCapacity"
    },
    "HealthCheckType": "ELB",
    "LaunchConfigurationName": {
     "Ref": "LaunchConfiguration"
    },
    "LoadBalancerNames": [
     {
      "Ref": "LoadBalancer"
     }
    ],
    "MaxSize": {
     "Ref": "ScaleCapacity"
    },
    "MinSize": {
     "Ref": "ScaleCapacity"
    },
    "Tags": [
     {
      "Key": "Environment",
      "PropagateAtLaunch": true,
      "Value": {
       "Ref": "EnvType"
      }
     }
    ],
    "VPCZoneIdentifier": [
     {
      "Ref": "ApiSubnet1"
     },
     {
      "Ref": "ApiSubnet2"
     }
    ]
   },
   "Type": "AWS::AutoScaling::AutoScalingGroup",
   "UpdatePolicy": {
    "AutoScalingReplacingUpdate": {
     "WillReplace": true
    },
    "AutoScalingRollingUpdate": {
     "MaxBatchSize": "1",
     "MinInstancesInService": "1",
     "PauseTime": "PT5M",
     "WaitOnResourceSignals": true
    }
   }
  },
  "HTTPRequestAlarm": {
   "Properties": {
    "AlarmActions": [
     {
      "Ref": "HTTPRequestScalingPolicy"
     }
    ],
    "AlarmDescription": "Alarm if HTTP Requests go above a 2000",
    "ComparisonOperator": "GreaterThanThreshold",
    "Dimensions": [
     {
      "Name": "LoadBalancerName",
      "Value": {
       "Ref": "LoadBalancer"
      }
     }
    ],
    "EvaluationPeriods": "1",
    "MetricName": "RequestCount",
    "Namespace": "AWS/SQS",
    "Period": "300",
    "Statistic": "Sum",
    "Threshold": "2000"
   },
   "Type": "AWS::CloudWatch::Alarm"
  },
  "HTTPRequestScalingPolicy": {
   "Properties": {
    "AdjustmentType": "ChangeInCapacity",
    "AutoScalingGroupName": {
     "Ref": "AutoscalingGroup"
    },
    "Cooldown": "1",
    "ScalingAdjustment": "1"
   },
   "Type": "AWS::AutoScaling::ScalingPolicy"
  },
  "LaunchConfiguration": {
   "Metadata": {
    "AWS::CloudFormation::Authentication": {
     "DeployUserAuth": {
      "accessKeyId": {
       "Ref": "DeployUserAccessKey"
      },
      "secretKey": {
       "Ref": "DeployUserSecretKey"
      },
      "type": "S3"
     }
    },
    "AWS::CloudFormation::Init": {
     "config": {
      "files": {
       "/etc/rsyslog.d/20-somethin.conf": {
        "authentication": "DeployUserAuth",
        "group": "root",
        "mode": "000644",
        "owner": "root",
        "source": {
         "Fn::Join": [
          "",
          [
           "http://",
           {
            "Ref": "DeployBucket"
           },
           ".s3.amazonaws.com/stacks/",
           {
            "Ref": "RootStackName"
           },
           "/env/etc/rsyslog.d/20-somethin.conf"
          ]
         ]
        }
       }
      },
      "services": {
       "sysvinit": {
        "rsyslog": {
         "enabled": true,
         "ensureRunning": true,
         "files": [
          "/etc/rsyslog.d/20-somethin.conf"
         ]
        }
       }
      }
     }
    }
   },
   "Properties": {
    "BlockDeviceMappings": [
     {
      "DeviceName": "/dev/sda1",
      "Ebs": {
       "VolumeSize": "8"
      }
     }
    ],
    "ImageId": {
     "Ref": "AmiId"
    },
    "InstanceType": "m1.small",
    "KeyName": {
     "Ref": "KeyName"
    },
    "SecurityGroups": [
     {
      "Ref": "SecurityGroup"
     }
    ],
    "UserData": {
     "Fn::Base64": {
      "Fn::Join": [
       "",
       [
        "#!/bin/bash\n",
        "cfn-signal -e 0",
        "    --resource AutoscalingGroup",
        "    --stack ",
        {
         "Ref": "AWS::StackName"
        },
        "    --region ",
        {
         "Ref": "AWS::Region"
        },
        "\n"
       ]
      ]
     }
    }
   },
   "Type": "AWS::AutoScaling::LaunchConfiguration"
  },
  "LoadBalancer": {
   "Properties": {
    "ConnectionDrainingPolicy": {
     "Enabled": true,
     "Timeout": 120
    },
    "CrossZone": true,
    "HealthCheck": {
     "HealthyThreshold": "5",
     "Interval": "20",
     "Target": "HTTP:80/",
     "Timeout": "15",
     "UnhealthyThreshold": "2"
    },
    "Listeners": [
     {
      "InstancePort": "80",
      "InstanceProtocol": "HTTP",
      "LoadBalancerPort": "443",
      "Protocol": "HTTPS",
      "SSLCertificateId": {
       "Ref": "SSLCertificateId"
      }
     }
    ],
    "LoadBalancerName": "api-lb",
    "Scheme": "internet-facing",
    "SecurityGroups": [
     {
      "Ref": "LoadBalancerSecurityGroup"
     }
    ],
    "Subnets": [
     {
      "Ref": "PublicSubnet1"
     },
     {
      "Ref": "PublicSubnet2"
     }
    ]
   },
   "Type": "AWS::ElasticLoadBalancing::LoadBalancer"
  }
 }
}
