    },
    "Name": "WebTarget",
    "Port": {
     "Ref": "WebServerPort"
    },
    "Protocol": "HTTP",
    "Targets": [
     {
      "Id": {
       "Ref": "WebInstance"
      },
      "Port": {
       "Ref": "WebServerPort"
      }
     }
    ],
    "UnhealthyThresholdCount": "3",
    "VpcId": {
     "Ref": "VpcId"
    }
   },
   "Type": "AWS::ElasticLoadBalancingV2::TargetGroup"
  },
  "WebInstance": {
   "Properties": {
    "ImageId": {
     "Fn::FindInMap": [
      "RegionMap",
      {
       "Ref": "AWS::Region"
      },
      "AMI"
     ]
    },
    "InstanceType": {
     "Ref": "InstanceType"
    },
    "KeyName": {
     "Ref": "KeyName"
    },
    "SecurityGroups": [
     {
      "Ref": "InstanceSecurityGroup"
     }
    ],
    "UserData": {
     "Fn::Base64": {
      "Ref": "WebServerPort"
     }
    }
   },
   "Type": "AWS::EC2::Instance"
  },
  "eipA": {
   "Properties": {
    "Domain": "vpc"
   },
   "Type": "AWS::EC2::EIP"
  },
  "eipB": {
   "Properties": {
    "Domain": "vpc"
   },
   "Type": "AWS::EC2::EIP"
  }
 }
